import com.workspace.platform.service.ModuleAccessService;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;
import java.util.Map;

@RestController
@RequestMapping("/api/modules")
public class ModuleController {

    private final ModuleAccessService moduleAccessService;

    public ModuleController(ModuleAccessService moduleAccessService) {
        this.moduleAccessService = moduleAccessService;
    }

    @GetMapping
    public ApiResponse<List<ModuleAccess>> findAll() {
        return ApiResponse.success(moduleAccessService.findAll());
    }

    @PutMapping("/{id}")
    public ApiResponse<ModuleAccess> update(@PathVariable("id") Long id,
                                            @RequestBody Map<String, Boolean> body,
                                            HttpServletRequest request) {
        String role = (String) request.getAttribute(JwtAuthFilter.ROLE_ATTRIBUTE);
        if (!"ADMIN".equals(role)) {
            return ApiResponse.error(403, "权限不足");
        }
        ModuleAccess updated = moduleAccessService.update(id, body.get("enabled"));
        if (updated == null) {
            return ApiResponse.error(404, "模块配置不存在");
        }
        return ApiResponse.success("更新成功", updated);
    }
}

package com.workspace.platform.controller;

import com.workspace.platform.dto.ApiResponse;
import com.workspace.platform.entity.Project;
import com.workspace.platform.filter.JwtAuthFilter;
import com.workspace.platform.service.ModuleAccessService;
import com.workspace.platform.service.ProjectService;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;
import java.util.Map;

@RestController
@RequestMapping("/api/projects")
public class ProjectController {

    private static final String MODULE_NAME = "PROJECT";

    private final ProjectService projectService;

    private final ModuleAccessService moduleAccessService;

    public ProjectController(ProjectService projectService, ModuleAccessService moduleAccessService) {
        this.projectService = projectService;
        this.moduleAccessService = moduleAccessService;
    }

    @GetMapping
    public ApiResponse<List<Project>> findAll(HttpServletRequest request) {
        if (!isAuthorized(request)) {
            return ApiResponse.error(403, "权限不足");
        }
        return ApiResponse.success(projectService.findAll());
    }

    @GetMapping("/{id}")
    public ApiResponse<Project> findById(@PathVariable("id") Long id, HttpServletRequest request) {
        if (!isAuthorized(request)) {
            return ApiResponse.error(403, "权限不足");
        }
        Project project = projectService.findById(id);
        if (project == null) {
            return ApiResponse.error(404, "项目不存在");
        }
        return ApiResponse.success(project);
    }

    @PostMapping
    public ApiResponse<Project> create(@RequestBody Map<String, String> body, HttpServletRequest request) {
        if (!isAuthorized(request)) {
            return ApiResponse.error(403, "权限不足");
        }
        Long creatorId = (Long) request.getAttribute(JwtAuthFilter.USER_ID_ATTRIBUTE);
        Project project = projectService.create(body.get("name"), body.get("description"), creatorId);
        return ApiResponse.success("创建成功", project);
    }

    @PutMapping("/{id}")
    public ApiResponse<Project> update(@PathVariable("id") Long id,
                                       @RequestBody Map<String, String> body,
                                       HttpServletRequest request) {
        if (!isAuthorized(request)) {
            return ApiResponse.error(403, "权限不足");
        }
        Project project = projectService.update(id, body.get("name"), body.get("description"), body.get("status"));
        if (project == null) {
            return ApiResponse.error(404, "项目不存在");
        }
        return ApiResponse.success("更新成功", project);
    }

    private boolean isAuthorized(HttpServletRequest request) {
        String role = (String) request.getAttribute(JwtAuthFilter.ROLE_ATTRIBUTE);
        return role != null && moduleAccessService.isModuleEnabled(MODULE_NAME, role);
    }
}

package com.workspace.platform.controller;

import com.workspace.platform.dto.ApiResponse;
import com.workspace.platform.entity.Task;
import com.workspace.platform.filter.JwtAuthFilter;
import com.workspace.platform.service.ModuleAccessService;
import com.workspace.platform.service.TaskService;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;
import java.util.Map;

@RestController
@RequestMapping("/api/tasks")
public class TaskController {

    private static final String MODULE_NAME = "TASK";

    private final TaskService taskService;

    private final ModuleAccessService moduleAccessService;

    public TaskController(TaskService taskService, ModuleAccessService moduleAccessService) {
        this.taskService = taskService;
        this.moduleAccessService = moduleAccessService;
    }

    @GetMapping
    public ApiResponse<List<Task>> findAll(HttpServletRequest request) {
        if (!isAuthorized(request)) {
            return ApiResponse.error(403, "权限不足");
        }
        return ApiResponse.success(taskService.findAll());
    }

    @GetMapping("/{id}")
    public ApiResponse<Task> findById(@PathVariable("id") Long id, HttpServletRequest request) {
        if (!isAuthorized(request)) {
            return ApiResponse.error(403, "权限不足");
        }
        Task task = taskService.findById(id);
        if (task == null) {
            return ApiResponse.error(404, "任务不存在");
        }
        return ApiResponse.success(task);
    }

    @PostMapping
    public ApiResponse<Task> create(@RequestBody Map<String, Object> body, HttpServletRequest request) {
        if (!isAuthorized(request)) {
            return ApiResponse.error(403, "权限不足");
        }
        String title = (String) body.get("title");
        Long projectId = toLong(body.get("projectId"));
        Long assigneeId = toLong(body.get("assigneeId"));
        Task task = taskService.create(title, projectId, assigneeId);
        return ApiResponse.success("创建成功", task);
    }

    private boolean isAuthorized(HttpServletRequest request) {
        String role = (String) request.getAttribute(JwtAuthFilter.ROLE_ATTRIBUTE);
        return role != null && moduleAccessService.isModuleEnabled(MODULE_NAME, role);
    }

    private Long toLong(Object value) {
        return value == null ? null : ((Number) value).longValue();
    }
}

package com.workspace.platform.dto;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

@Data
@NoArgsConstructor
@AllArgsConstructor
public class ApiResponse<T> {

    private int code;

    private String message;

    private T data;

    public static <T> ApiResponse<T> success(T data) {
        return new ApiResponse<>(200, "success", data);
    }

    public static <T> ApiResponse<T> success(String message, T data) {
        return new ApiResponse<>(200, message, data);
    }

    public static <T> ApiResponse<T> error(int code, String message) {
        return new ApiResponse<>(code, message, null);
    }
}

